% Q 2012 2
\QuestionPage{2.2 求导的基本法则}{选择题}{2012 年第 2 题}{1}{乘积求导}{056 / 234}
设函数$f(x) = (\mathrm{e}^x - 1)(\mathrm{e}^{2x} - 2) \cdots(\mathrm{e}^{nx} - n)$，其中$n$为正整数，则$f'(0) =$\pickout{}
\begin{abcd}
\item $(- 1)^{n - 1}(n - 1)!$．
\item $(- 1)^n(n - 1)!$．
\item $(- 1)^{n - 1} n!$．
\item $(- 1)^n n!$．
\end{abcd}
\QuestionEnd

\begin{QuestionSolution}{2012 年第 2 题}
\textbf{入手角度}\quad 乘积中只有第一因子在零点为零，求导后仅求这一因子导数的项能留下。

\textbf{解析}\quad 写 \(f(x)=(\mathrm{e}^x-1)P(x)\)，其中 \(P(x)=\prod_{k=2}^n(\mathrm{e}^{kx}-k)\)，\(n=1\) 时空积取 \(1\)。由乘积法则，
\[
f'(0)=P(0)=\prod_{k=2}^n(1-k)=(-1)^{n-1}(n-1)!.
\]
选 A。
\end{QuestionSolution}

% Q 2013 2
\QuestionPage{2.2 求导的基本法则}{选择题}{2013 年第 2 题}{1}{隐函数求导与极限}{057 / 234}
设函数$y = f(x)$由方程$\cos (xy) + \ln y - x = 1$确定，
则$\lim_{n \to \infty} n\left[f\left(\frac{2}{n} \right) - 1 \right] =$\pickout{}
\begin{abcd}
\item $2$．
\item $1$．
\item $- 1$．
\item $- 2$．
\end{abcd}
\QuestionEnd

\begin{QuestionSolution}{2013 年第 2 题}
\textbf{入手角度}\quad 先从隐式方程确定 \(f(0)\)，然后将数列极限改写为零点的差商。

\textbf{解析}\quad 令 \(x=0\)，得 \(\ln y=0\)，故 \(f(0)=1\)。对方程求导得
\[
-\sin(xy)(y+xy')+\frac{y'}y-1=0.
\]
在 \((0,1)\) 得 \(f'(0)=1\)。因此 \(n[f(\frac{2}{n})-1]=\frac{2[f(\frac{2}{n})-f(0)]}{\frac{2}{n}}\to2f'(0)=\boxed{2}\)。选 A。
\end{QuestionSolution}

% Q 2021 3
\QuestionPage{2.2 求导的基本法则}{选择题}{2021 年第 3 题}{1}{圆柱体的相关变化率}{058 / 234}
有一圆柱体底面半径与高随时间变化的速率分别为 \(2\,\mathrm{cm}\,\mathrm{s}^{-1}\)、\(-3\,\mathrm{cm}\,\mathrm{s}^{-1}\)。当底面半径为 \(10\,\mathrm{cm}\)，高为 \(5\,\mathrm{cm}\) 时，圆柱体的体积与表面积随时间变化的速率分别为
\choices{\(125\pi\,\mathrm{cm}^{3}\,\mathrm{s}^{-1}\)，\(40\pi\,\mathrm{cm}^{2}\,\mathrm{s}^{-1}\)}{\(125\pi\,\mathrm{cm}^{3}\,\mathrm{s}^{-1}\)，\(-40\pi\,\mathrm{cm}^{2}\,\mathrm{s}^{-1}\)}{\(-100\pi\,\mathrm{cm}^{3}\,\mathrm{s}^{-1}\)，\(40\pi\,\mathrm{cm}^{2}\,\mathrm{s}^{-1}\)}{\(-100\pi\,\mathrm{cm}^{3}\,\mathrm{s}^{-1}\)，\(-40\pi\,\mathrm{cm}^{2}\,\mathrm{s}^{-1}\)}
\QuestionEnd

\begin{QuestionSolution}{2021 年第 3 题}
\textbf{入手角度}\quad 将半径和高都视为时间函数，表面积要包含两个底面。

\textbf{解析}\quad 设半径为 \(r\)，高为 \(h\)，则
\[
\begin{aligned}
V'&=\pi(2rr'h+r^2h'),\\
S'&=2\pi(2rr'+r'h+rh').
\end{aligned}
\]
代入 \(r=10,h=5,r'=2,h'=-3\)，得到 \(V'=-100\pi\,\mathrm{cm}^3\,\mathrm{s}^{-1}\) 与 \(S'=40\pi\,\mathrm{cm}^2\,\mathrm{s}^{-1}\)。选 C。
\end{QuestionSolution}

% Q 2023 5
\QuestionPage{2.2 求导的基本法则}{选择题}{2023 年第 5 题}{1}{参数方程与可导性}{059 / 234}
设函数 \(y=f(x)\) 由
\[\begin{cases}
x=2t+|t|,\\
y=|t|\sin t
\end{cases}
\]
确定，则（ ）。
\choices{\(f(x)\) 连续，\(f'(0)\) 不存在}{\(f'(0)\) 存在，\(f'(x)\) 在 \(x=0\) 处不连续}{\(f'(x)\) 连续，\(f''(0)\) 不存在}{\(f''(0)\) 存在，\(f''(x)\) 在 \(x=0\) 处不连续}
\QuestionEnd

\begin{QuestionSolution}{2023 年第 5 题}
\textbf{入手角度}\quad 参数变号时 \(x\) 关于 \(t\) 的比例不同，先消参写出左右两段再比较导数。

\textbf{解析}\quad \(t\ge0\) 时 \(x=3t\)，\(t<0\) 时 \(x=t\)，故
\[
f(x)=
\begin{cases}
(\frac{x}{3})\sin(\frac{x}{3}),&x\ge0,\\
-x\sin x,&x<0.
\end{cases}
\]
差商 \(\frac{f(x)}{x}\to0\)，得 \(f'(0)=0\)。在正半轴 \(f'=\frac{\sin(\frac{x}{3})}{3}+\frac{x\cos(\frac{x}{3})}{9}\)，在负半轴 \(f'=-\sin x-x\cos x\)，左右都趋于零，故 \(f'\) 连续。然而 \(\frac{f'(x)}{x}\) 的右极限为 \(\frac{2}{9}\)，左极限为 \(-2\)，所以 \(f''(0)\) 不存在，选 C。
\end{QuestionSolution}

% Q 2024 2
\QuestionPage{2.2 求导的基本法则}{选择题}{2024 年第 2 题}{1}{参数方程求导与导数定义}{060 / 234}
已知
\[\left\{
\begin{aligned}
x &= 1+t^3,\\
y &= \mathrm{e}^{t^2},
\end{aligned}
\right.
\]
则
\[\lim_{x\to+\infty}x\!\left[f\!\left(2+\frac{2}{x}\right)-f(2)\right]
\]
等于（ ）
\choices{\(2\mathrm{e}\)}{\(\frac{4}{3}\mathrm{e}\)}{\(\frac{2}{3}\mathrm{e}\)}{\(\frac{\mathrm{e}}{3}\)}
\QuestionEnd

\begin{QuestionSolution}{2024 年第 2 题}
\textbf{入手角度}\quad 令 \(h=\frac{2}{x}\) 得到 \(x=2\) 处的右差商，导数可直接通过参数求出。

\textbf{解析}\quad \(x=2\) 对应 \(t=1\)，而
\[
\left.\frac{\mathrm{d}y}{\mathrm{d}x}\right|_{t=1}
=\left.\frac{2t \mathrm{e}^{t^2}}{3t^2}\right|_{t=1}=\frac{2\mathrm{e}}{3}.
\]
原式写为 \(\frac{2[f(2+h)-f(2)]}{h}\)，当 \(x\to+\infty\) 时 \(h\to0^+\)。所求极限为 \(2f'(2)=\boxed{\frac{4\mathrm{e}}{3}}\)，选 B。
\end{QuestionSolution}

% Q 2026 6
\QuestionPage{2.2 求导的基本法则}{选择题}{2026 年第 6 题}{1}{反函数与变上限积分求导}{061 / 234}
已知函数
\[f(x)=\int_1^{x^3}\frac{\mathrm{e}^t}{1+t^2}\,\mathrm{d}t,
\]
\(f\) 的反函数为 \(g\)，则
\choices{\(g(0)=1,\ g'(0)=\dfrac{3}{2\mathrm{e}}\)}{\(g(0)=1,\ g'(0)=\dfrac{2}{3\mathrm{e}}\)}{\(g(1)=0,\ g'(1)=\dfrac{3}{2\mathrm{e}}\)}{\(g(1)=0,\ g'(1)=\dfrac{2}{3\mathrm{e}}\)}
\QuestionEnd

\begin{QuestionSolution}{2026 年第 6 题}
\textbf{入手角度}\quad 上下限相等时积分为零，先确定反函数的取值点，再取原导数的倒数。

\textbf{解析}\quad 被积函数恒正且 \(x^3\) 严格递增，故 \(f\) 严格递增。\(f(1)=0\)，所以 \(g(0)=1\)。微积分基本定理给出
\[
f'(x)=3x^2\frac{\mathrm{e}^{x^3}}{1+x^6},\qquad f'(1)=\frac{3\mathrm{e}}{2}.
\]
因此 \(g'(0)=\frac{1}{f'(1)}=\boxed{\frac{2}{3\mathrm{e}}}\)，选 B。
\end{QuestionSolution}

% Q 2009 12
\QuestionPage{2.2 求导的基本法则}{填空题}{2009 年第 12 题}{2}{隐函数求导}{062 / 234}
设$y = y(x)$是由方程$xy + \mathrm{e}^y = x + 1$确定的隐函数，
则$\frac{\partial{}^2 y}{\partial{} x^2}\Big|_{x = 0} =$ \blank{}．
\QuestionEnd

\begin{QuestionSolution}{2009 年第 12 题}
\textbf{入手角度}\quad 两次隐式求导，在第二次求导式中代入点值和已求的一阶导数。

\textbf{解析}\quad \(x=0\) 时 \(\mathrm{e}^y=1\)，故 \(y(0)=0\)。一次求导得 \(y+(x+\mathrm{e}^y)y'=1\)，因此 \(y'(0)=1\)。再次求导得
\[
2y'+\mathrm{e}^y(y')^2+(x+\mathrm{e}^y)y''=0.
\]
代入 \(x=0,y=0,y'=1\)，得 \(\boxed{y''(0)=-3}\)。
\end{QuestionSolution}

% Q 2010 11
\QuestionPage{2.2 求导的基本法则}{填空题}{2010 年第 11 题}{2}{对数函数的高阶导数}{063 / 234}
函数$y = \ln(1 - 2x)$在$x = 0$处的$n$阶导数$y^{(n)}(0) =$ \blank{}．
\QuestionEnd

\begin{QuestionSolution}{2010 年第 11 题}
\textbf{入手角度}\quad 对数在零点的幂级数直接给出每一阶导数对应的系数。

\textbf{解析}\quad 在 \(|2x|<1\) 内，
\[
\ln(1-2x)=-\sum_{k=1}^{\infty}\frac{2^k}{k}x^k.
\]
对于 \(n\ge1\)，\(x^n\) 的系数等于 \(\frac{y^{(n)}(0)}{n!}\)，因此 \(\boxed{y^{(n)}(0)=-2^n(n-1)!}\)。
\end{QuestionSolution}

% Q 2010 13
\QuestionPage{2.2 求导的基本法则}{填空题}{2010 年第 13 题}{2}{相关变化率}{064 / 234}
已知一个长方形的长$l$以$2\,\mathrm{cm}\,\mathrm{s}^{-1}$的速率增加，宽$w$以$3\,\mathrm{cm}\,\mathrm{s}^{-1}$的速率增加．
则当$l = 12\text{cm}$，$w = 5\text{cm}$时，它的对角线增加的速率为 \blank{}．
\QuestionEnd

\begin{QuestionSolution}{2010 年第 13 题}
\textbf{入手角度}\quad 利用勾股关系对时间求导，避免先把长和宽显式写成时间函数。

\textbf{解析}\quad 设对角线长为 \(d\)，则 \(d^2=l^2+w^2\)，从而 \(dd'=ll'+ww'\)。在题给时刻 \(d=\sqrt{12^2+5^2}=13\)，代入得
\[
d'=\frac{12\cdot2+5\cdot3}{13}=\boxed{3\,\mathrm{cm}\,\mathrm{s}^{-1}}.
\]
\end{QuestionSolution}

